#include <bits/stdc++.h>
#include <tr1/unordered_map>
using namespace std;

void fastRead(int &v) {
    char c;
    v = 0;
    bool negative = false;
    while (!isdigit(c = getchar_unlocked())) {
        if (c == '-') negative = true;
    }
    do {
        v = (v << 3) + (v << 1) + (c ^ '0');
    } while (isdigit(c = getchar_unlocked()));
    if (negative) v = -v;
}

void fastRead(long long &v) {
    char c;
    v = 0;
    bool negative = false;
    while (!isdigit(c = getchar_unlocked())) {
        if (c == '-') negative = true;
    }
    do {
        v = (v << 3) + (v << 1) + (c ^ '0');
    } while (isdigit(c = getchar_unlocked()));
    if (negative) v = -v;
}

long long n, k, MOD;
int factorial[262155];
int invFactorial[262155];

int modExponentiation(int base, long long exp) {
    int result = 1;
    while (exp) {
        if (exp & 1) {
            result = (long long)result * base % MOD;
        }
        base = (long long)base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int memo[262155][31];
bool processed[262155][31];
int log2Val[262155];

int getPowerOfTwo(int x) {
    int cnt = 0;
    while ((x & 1) == 0 && x) {
        ++cnt;
        x >>= 1;
    }
    return cnt;
}

int powerCount[262155];

int comb(int N, int M) {
    return (long long)factorial[N] * invFactorial[M] % MOD * invFactorial[N - M] % MOD;
}

int solveRec(int N, int K) {
    if (N == 0) return 1;
    if (K == 0) return 0;
    if (memo[N][K] != -1) return memo[N][K];

    int step = 1 << log2Val[N];
    int sum = 0;
    for (int i = N; i >= step; i -= 2) {
        sum = (sum + (long long)comb(N, i) * solveRec(N - i, K - 1) % MOD * K) % MOD;
    }
    return memo[N][K] = sum;
}

vector<pair<int, int>> seq;

int solveIter(int N, int K) {
    queue<pair<int, int>> q;
    q.emplace(N, K);

    while (!q.empty()) {
        auto [curN, curK] = q.front(); q.pop();
        seq.emplace_back(curN, curK);

        if (curN == 0 || curK == 0) continue;

        int step = 1 << log2Val[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (powerCount[i] + powerCount[curN - i] == powerCount[curN] && !processed[curN - i][curK - 1]) {
                processed[curN - i][curK - 1] = true;
                q.emplace(curN - i, curK - 1);
            }
        }
    }

    for (int i = seq.size() - 1; i >= 0; --i) {
        auto [curN, curK] = seq[i];
        if (curN == 0) {
            memo[curN][curK] = 1;
            continue;
        }
        if (curK == 0) {
            memo[curN][curK] = 0;
            continue;
        }

        int step = 1 << log2Val[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (powerCount[i] + powerCount[curN - i] == powerCount[curN]) {
                memo[curN][curK] = (memo[curN][curK] + (long long)comb(curN, i) * memo[curN - i][curK - 1] % MOD * curK) % MOD;
            }
        }
    }

    return memo[N][K];
}

int main() {
    fastRead(n);
    fastRead(k);
    fastRead(MOD);

    factorial[0] = 1;
    memset(processed, 0, sizeof(processed));
    log2Val[0] = -1;

    for (int i = 1; i <= 262150; ++i) {
        factorial[i] = (long long)factorial[i - 1] * i % MOD;
        log2Val[i] = log2Val[i >> 1] + 1;
        powerCount[i] = powerCount[i - 1] + getPowerOfTwo(i);
    }

    invFactorial[262150] = modExponentiation(factorial[262150], MOD - 2);
    for (int i = 262149; i >= 1; --i) {
        invFactorial[i] = (long long)invFactorial[i + 1] * (i + 1) % MOD;
    }

    invFactorial[0] = invFactorial[1];

    if (n & 1) {
        cout << modExponentiation(k, n) << '\n';
    } else {
        int total = modExponentiation(k, n);
        int result = solveIter(n, k);
        cout << ((total - result) % MOD + MOD) % MOD;
    }
}
